import{_ as p,a0 as l,w as o,s as u,I as a,x as s,a1 as t,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何從 Linux 終端發送桌面通知與提醒 | LCTT x X-CMD","titleTemplate":false,"description":"如何從 Linux 終端發送桌面通知與提醒 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從 Linux 終端發送桌面通知與提醒 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從 Linux 終端發送桌面通知與提醒 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220106 Send desktop notifications and reminders from Linux terminal","title":"如何從 Linux 終端發送桌面通知與提醒","tag":"202207","desc":""},"relativePath":"202207/20220106 Send desktop notifications and reminders from Linux terminal.md","filePath":"[post].md"}'),r={name:"202207/20220106 Send desktop notifications and reminders from Linux terminal.md"};function c(h,n,f,m,g,k){const i=l("Link");return o(),u("div",null,[n[26]||(n[26]=a("h1",{id:"如何從-linux-終端發送桌面通知與提醒",tabindex:"-1"},[s("如何從 Linux 終端發送桌面通知與提醒 "),a("a",{class:"header-anchor",href:"#如何從-linux-終端發送桌面通知與提醒","aria-label":"Permalink to “如何從 Linux 終端發送桌面通知與提醒”"},"​")],-1)),n[27]||(n[27]=a("blockquote",null,[a("p",null,"這篇教程演示如何使用腳本命令來發送自己的桌面通知與提醒。")],-1)),n[28]||(n[28]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/14/145103vawkhy6w506thy6h.jpg",alt:""})],-1)),n[29]||(n[29]=a("p",null,"有時候，來自腳本的視覺回饋是很有用的。例如，當一個腳本或計劃任務完成時，一個長期運行的構建任務失敗時，或者當腳本執行中出現了緊急問題時。桌面應用程序可以通過彈出通知來做到這一點，但腳本也可以做到這一點！你可以使用腳本命令來給自己發送桌面通知與提醒。",-1)),n[30]||(n[30]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/buyeggs.png",alt:"Example notification",title:"Example notification"})],-1)),a("p",null,[n[1]||(n[1]=s("下面的代碼是在 Linux 上編寫和測試的。它也可以在 macOS 上運行，只需花點功夫。請參見最後一節 ",-1)),t(i,{href:"https://opensource.com/article/22/1/linux-desktop-notifications/#script-notifications-on-macOS"},{default:e(()=>[...n[0]||(n[0]=[s("提示與技巧",-1)])]),_:1}),n[2]||(n[2]=s("。",-1))]),n[31]||(n[31]=a("h3",{id:"從-linux-終端發送通知",tabindex:"-1"},[s("從 Linux 終端發送通知 "),a("a",{class:"header-anchor",href:"#從-linux-終端發送通知","aria-label":"Permalink to “從 Linux 終端發送通知”"},"​")],-1)),a("p",null,[n[4]||(n[4]=s("要從 Linux 終端發送通知，請使用 ",-1)),t(i,{href:"https://manpages.ubuntu.com/manpages/xenial/man1/notify-send.1.html"},{default:e(()=>[...n[3]||(n[3]=[s("notify-send",-1)])]),_:1}),n[5]||(n[5]=s(" 命令。運行 ",-1)),n[6]||(n[6]=a("code",null,"which notify-send",-1)),n[7]||(n[7]=s(" 命令來查看它是否在於你的系統中。如果沒有，請使用包管理器來安裝它。",-1))]),n[32]||(n[32]=d(`<p>在 Fedora 上，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install notify-send</span></span></code></pre></div><p>在基於 Debian 的發行版上，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install notify-send</span></span></code></pre></div><p>幾個簡單的通知示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ notify-send &quot;Dinner ready!&quot;</span></span>
<span class="line"><span>$ notify-send &quot;Tip of the Day&quot; &quot;How about a nap?&quot;</span></span></code></pre></div><p>你可以用緊急程度、自定義圖標等選項來自定義通知。過 <code>man notify-send</code> 瞭解更多。你也可以在通知正文中使用一小組 HTML 標記，以使消息有一個棒的視覺感受。最重要的是，URL 被呈現為可點擊的。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ notify-send -u critical \\</span></span>
<span class="line"><span>  &quot;Build failed!&quot; \\</span></span>
<span class="line"><span>  &quot;There were &lt;b&gt;123&lt;/b&gt; errors. Click here to see the results: http://buildserver/latest&quot;</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/buildfail.png" alt="Build fail notification" title="Build fail notification"></p><p>發送的通知會被桌面環境接收，並像其他通知一樣顯示。它們將具有相同的外觀、交互和行為。</p><h3 id="將-notify-send-與-at-結合使用" tabindex="-1">將 notify-send 與 at 結合使用 <a class="header-anchor" href="#將-notify-send-與-at-結合使用" aria-label="Permalink to “將 notify-send 與 at 結合使用”">​</a></h3><p>計劃任務通常被用來定期安排命令。<code>at</code> 命令安排在一個指定的時間執行一條命令。如果你像這樣運行它，它會以交互模式啓動，你可以在其中輸入要在指定時間執行的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 12:00</span></span></code></pre></div><p>這對腳本來説並不有用。幸運的是 <code>at</code> 接受來自標準輸入的參數，所以我們可以這樣使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;npm run build&quot; | at now + 1 minute</span></span>
<span class="line"><span>$ echo &quot;backup-db&quot; | at 13:00</span></span></code></pre></div><p>有許多指定時間的方法。 從絕對時間，如 <code>10:00</code>，到相對時間，如 <code>now + 2 hours</code> ，再特殊時間，如<code>noon</code> 或 <code>midnight</code>。我們可以把它和 <code>notify-send</code> 結合起來，在未來的某個時間向自己發送提醒。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;notify-send &#39;Stop it and go home now?&#39; &#39;Enough work for today.&#39; -u critical&quot; | at now</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/stop-it.png" alt="Stop for the day notification" title="Stop for the day notification"></p><h3 id="提醒的命令" tabindex="-1">提醒的命令 <a class="header-anchor" href="#提醒的命令" aria-label="Permalink to “提醒的命令”">​</a></h3><p>現在，建立一個自定義的 Bash 命令來給自己發送提醒信息。像這樣簡單且人性化的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ remind &quot;I&#39;m still here&quot; now</span></span>
<span class="line"><span>$ remind &quot;Time to wake up!&quot; in 5 minutes</span></span>
<span class="line"><span>$ remind &quot;Dinner&quot; in 1 hour</span></span>
<span class="line"><span>$ remind &quot;Take a break&quot; at noon</span></span>
<span class="line"><span>$ remind &quot;It&#39;s Friday pints time!&quot; at 17:00</span></span></code></pre></div><p>這比 Alexa 更好！該怎樣做？</p><p>請看下面的代碼。它定義了一個名為 <code>remind</code> 的函數，它支持上述語法。實際工作是在最後兩行完成的。其餘的部分負責顯示幫助信息、參數校驗等，這與任何大型應用程序中有用的代碼與必要的白噪聲的比例大致相同。</p><p>把代碼保存在某個地方，例如，在 <code>~/bin/remind</code> 文件中，並在你的 <code>.bashrc</code> 配置文件寫入該函數，以便在你登錄時加載它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/bin/remind</span></span></code></pre></div><p>重新打開終端，然後輸入 <code>remind</code> 來查看語法。盡情享受吧！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env bash</span></span>
<span class="line"><span>function remind () {</span></span>
<span class="line"><span>  local COUNT=&quot;$#&quot;</span></span>
<span class="line"><span>  local COMMAND=&quot;$1&quot;</span></span>
<span class="line"><span>  local MESSAGE=&quot;$1&quot;</span></span>
<span class="line"><span>  local OP=&quot;$2&quot;</span></span>
<span class="line"><span>  shift 2</span></span>
<span class="line"><span>  local WHEN=&quot;$@&quot;</span></span>
<span class="line"><span>  # Display help if no parameters or help command</span></span>
<span class="line"><span>  if [[ $COUNT -eq 0 || &quot;$COMMAND&quot; == &quot;help&quot; || &quot;$COMMAND&quot; == &quot;--help&quot; || &quot;$COMMAND&quot; == &quot;-h&quot; ]]; then</span></span>
<span class="line"><span>    echo &quot;COMMAND&quot;</span></span>
<span class="line"><span>    echo &quot;    remind &amp;lt;message&amp;gt; &amp;lt;time&amp;gt;&quot;</span></span>
<span class="line"><span>    echo &quot;    remind &amp;lt;command&amp;gt;&quot;</span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;DESCRIPTION&quot;</span></span>
<span class="line"><span>    echo &quot;    Displays notification at specified time&quot;</span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;EXAMPLES&quot;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Hi there&quot; now&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Time to wake up&quot; in 5 minutes&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Dinner&quot; in 1 hour&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Take a break&quot; at noon&#39;</span></span>
<span class="line"><span>    echo &#39;    remind &quot;Are you ready?&quot; at 13:00&#39;</span></span>
<span class="line"><span>    echo &#39;    remind list&#39;</span></span>
<span class="line"><span>    echo &#39;    remind clear&#39;</span></span>
<span class="line"><span>    echo &#39;    remind help&#39;</span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Check presence of AT command</span></span>
<span class="line"><span>  if ! which at &amp;gt;/dev/null; then</span></span>
<span class="line"><span>    echo &quot;remind: AT utility is required but not installed on your system. Install it with your package manager of choice, for example &#39;sudo apt install at&#39;.&quot;</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Run commands: list, clear</span></span>
<span class="line"><span>  if [[ $COUNT -eq 1 ]]; then</span></span>
<span class="line"><span>    if [[ &quot;$COMMAND&quot; == &quot;list&quot; ]]; then</span></span>
<span class="line"><span>      at -l</span></span>
<span class="line"><span>    elif [[ &quot;$COMMAND&quot; == &quot;clear&quot; ]]; then</span></span>
<span class="line"><span>      at -r $(atq | cut -f1)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>      echo &quot;remind: unknown command $COMMAND. Type &#39;remind&#39; without any parameters to see syntax.&quot;</span></span>
<span class="line"><span>    fi</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Determine time of notification</span></span>
<span class="line"><span>  if [[ &quot;$OP&quot; == &quot;in&quot; ]]; then</span></span>
<span class="line"><span>    local TIME=&quot;now + $WHEN&quot;</span></span>
<span class="line"><span>  elif [[ &quot;$OP&quot; == &quot;at&quot; ]]; then</span></span>
<span class="line"><span>    local TIME=&quot;$WHEN&quot;</span></span>
<span class="line"><span>  elif [[ &quot;$OP&quot; == &quot;now&quot; ]]; then</span></span>
<span class="line"><span>    local TIME=&quot;now&quot;</span></span>
<span class="line"><span>  else</span></span>
<span class="line"><span>    echo &quot;remind: invalid time operator $OP&quot;</span></span>
<span class="line"><span>    return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  # Schedule the notification</span></span>
<span class="line"><span>  echo &quot;notify-send &#39;$MESSAGE&#39; &#39;Reminder&#39; -u critical&quot; | at $TIME 2&amp;gt;/dev/null</span></span>
<span class="line"><span>  echo &quot;Notification scheduled at $TIME&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="簡單的提醒" tabindex="-1">簡單的提醒 <a class="header-anchor" href="#簡單的提醒" aria-label="Permalink to “簡單的提醒”">​</a></h3><p>通過這幾個簡單的開源命令，你可以將你自己的腳本、應用程序和任務與你的桌面結合起來。試一試吧！</p><hr><p>（文內圖片來自 Tomasz Waraksa, CC BY-SA 4.0）</p>`,31)),a("p",null,[n[9]||(n[9]=s("本文經作者許可改編自 ",-1)),t(i,{href:"https://letsdebug.it/post/30-linux-desktop-notifications/"},{default:e(()=>[...n[8]||(n[8]=[s("原文",-1)])]),_:1}),n[10]||(n[10]=s("。",-1))]),n[33]||(n[33]=a("hr",null,null,-1)),a("p",null,[n[12]||(n[12]=s("via: ",-1)),t(i,{href:"https://opensource.com/article/22/1/linux-desktop-notifications"},{default:e(()=>[...n[11]||(n[11]=[s("https://opensource.com/article/22/1/linux-desktop-notifications",-1)])]),_:1})]),a("p",null,[n[17]||(n[17]=s("作者：",-1)),t(i,{href:"https://opensource.com/users/tomasz"},{default:e(()=>[...n[13]||(n[13]=[s("Tomasz Waraksa",-1)])]),_:1}),n[18]||(n[18]=s(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...n[14]||(n[14]=[s("lujun9972",-1)])]),_:1}),n[19]||(n[19]=s(" 譯者：",-1)),t(i,{href:"https://github.com/mcfd"},{default:e(()=>[...n[15]||(n[15]=[s("mcfd",-1)])]),_:1}),n[20]||(n[20]=s(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...n[16]||(n[16]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[23]||(n[23]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[21]||(n[21]=[s("LCTT",-1)])]),_:1}),n[24]||(n[24]=s(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...n[22]||(n[22]=[s("Linux中國",-1)])]),_:1}),n[25]||(n[25]=s(" 榮譽推出",-1))])])}const x=p(r,[["render",c]]);export{y as __pageData,x as default};
